// =============================================================================
// NOTIFICACION.JSX - SISTEMA DE NOTIFICACIONES TOAST
// =============================================================================
// Este componente muestra notificaciones temporales en la esquina de la pantalla.
// Similar a los "toasts" de Android o las notificaciones de sistemas operativos.
//
// CARACTERÍSTICAS:
// - Aparece automáticamente cuando se muestra un mensaje
// - Desaparece automáticamente después de 3 segundos
// - Animación suave de entrada y salida
// - Posición fija en la esquina inferior derecha
// =============================================================================

import React, { useEffect } from 'react';

/**
 * COMPONENTE: Notificacion
 * 
 * PROPS:
 * @param {string} mensaje - El mensaje a mostrar
 * @param {function} onClose - Función que se ejecuta cuando la notificación se cierra
 * @param {string} tipo - Tipo de notificación ('exito', 'error', 'info', 'advertencia')
 * @param {number} duracion - Tiempo en ms antes de auto-cerrar (default: 3000)
 * 
 * CONCEPTO: Toast Notification
 * Notificación temporal que aparece y desaparece automáticamente.
 * No bloquea la interacción del usuario (a diferencia de los alerts).
 */
const Notificacion = ({ 
    mensaje, 
    onClose, 
    tipo = 'exito',
    duracion = 3000 
}) => {

    // =========================================================================
    // 1. EFECTO: AUTO-CIERRE
    // =========================================================================
    /**
     * useEffect para cerrar automáticamente la notificación
     * 
     * FLUJO:
     * 1. Notificación aparece
     * 2. setTimeout programa el cierre en X milisegundos
     * 3. Después de X ms, ejecuta onClose()
     * 4. onClose elimina la notificación del DOM
     * 
     * CLEANUP:
     * Si el componente se desmonta antes del timeout,
     * clearTimeout cancela el timer para evitar errores
     */
    useEffect(() => {
        // Programar el auto-cierre
        const timer = setTimeout(() => {
            onClose();
        }, duracion);

        // CLEANUP: Cancelar el timer si el componente se desmonta
        return () => clearTimeout(timer);
    }, [onClose, duracion]);  // Re-ejecutar si estas props cambian

    // =========================================================================
    // 2. CONFIGURACIÓN SEGÚN TIPO
    // =========================================================================
    /**
     * Diferentes estilos y íconos según el tipo de notificación
     * 
     * CONCEPTO: Switch Statement con Return
     * Una forma elegante de manejar múltiples casos
     */
    const getTipoConfig = () => {
        switch (tipo) {
            case 'exito':
                return {
                    icono: '✓',
                    color: 'linear-gradient(135deg, #0099ff, #00cc88)',
                    iconoBg: '#00cc88'
                };
            case 'error':
                return {
                    icono: '✕',
                    color: 'linear-gradient(135deg, #ff4444, #cc0000)',
                    iconoBg: '#ff4444'
                };
            case 'info':
                return {
                    icono: 'ℹ',
                    color: 'linear-gradient(135deg, #5BC0DE, #3498db)',
                    iconoBg: '#5BC0DE'
                };
            case 'advertencia':
                return {
                    icono: '⚠',
                    color: 'linear-gradient(135deg, #f39c12, #e67e22)',
                    iconoBg: '#f39c12'
                };
            default:
                return {
                    icono: '✓',
                    color: 'linear-gradient(135deg, #0099ff, #00cc88)',
                    iconoBg: '#00cc88'
                };
        }
    };

    const config = getTipoConfig();

    // =========================================================================
    // 3. ESTILOS
    // =========================================================================

    // Estilo del contenedor principal
    const notificacionStyle = {
        position: 'fixed',          // Posición fija en la pantalla
        bottom: '20px',             // 20px desde el borde inferior
        right: '20px',              // 20px desde el borde derecho
        background: config.color,   // Color según el tipo
        color: 'white',
        padding: '15px 20px',
        borderRadius: '10px',
        boxShadow: '0 10px 30px rgba(0, 0, 0, 0.3)',
        display: 'flex',
        alignItems: 'center',
        gap: '12px',
        zIndex: 10000,              // Muy alto para aparecer encima de todo
        minWidth: '250px',
        maxWidth: '400px',
        animation: 'slideIn 0.4s ease, fadeOut 0.4s ease ' + (duracion - 400) + 'ms',
        cursor: 'pointer',
        width: '100px',
        height: 'auto'
    };

    // Estilo del ícono
    const iconoStyle = {
        width: '28px',
        height: '28px',
        borderRadius: '50%',
        background: 'rgba(255, 255, 255, 0.3)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontSize: '18px',
        fontWeight: 'bold',
        flexShrink: 0              // No reducir tamaño
    };

    // Estilo del texto del mensaje
    const mensajeStyle = {
        flex: 1,                   // Ocupar todo el espacio disponible
        fontSize: '15px',
        lineHeight: '1.4'
    };

    // Estilo del botón cerrar
    const closeButtonStyle = {
        background: 'rgba(255, 255, 255, 0.2)',
        border: 'none',
        borderRadius: '50%',
        width: '24px',
        height: '24px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: 'pointer',
        color: 'white',
        fontSize: '16px',
        transition: 'all 0.2s ease',
        flexShrink: 0
    };

    // =========================================================================
    // 4. RENDERIZADO
    // =========================================================================
    /**
     * ESTRUCTURA HTML:
     * 
     * <div> (notificación)
     *   ├── <div> (ícono)
     *   ├── <span> (mensaje)
     *   └── <button> (cerrar)
     */

    return (
        <>
            {/* ESTILOS DE ANIMACIÓN */}
            <style>{`
                /* Animación de entrada (deslizar desde la derecha) */
                @keyframes slideIn {
                    from {
                        transform: translateX(400px);
                        opacity: 0;
                    }
                    to {
                        transform: translateX(0);
                        opacity: 1;
                    }
                }

                /* Animación de salida (desvanecer) */
                @keyframes fadeOut {
                    from {
                        opacity: 1;
                    }
                    to {
                        opacity: 0;
                    }
                }

                /* Efecto hover en la notificación */
                .notificacion:hover {
                    transform: translateY(-2px);
                    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.4);
                }
            `}</style>

            {/* NOTIFICACIÓN */}
            <div 
                className="notificacion"
                style={notificacionStyle}
                onClick={onClose}  // Cerrar al hacer clic en cualquier parte
            >
                {/* ÍCONO */}
                <div style={iconoStyle}>
                    {config.icono}
                </div>

                {/* MENSAJE */}
                <span style={mensajeStyle}>
                    {mensaje}
                </span>

                {/* BOTÓN CERRAR */}
                <button
                    style={closeButtonStyle}
                    onClick={onClose}
                    onMouseEnter={(e) => {
                        e.target.style.background = 'rgba(255, 255, 255, 0.3)';
                        e.target.style.transform = 'scale(1.1)';
                    }}
                    onMouseLeave={(e) => {
                        e.target.style.background = 'rgba(255, 255, 255, 0.2)';
                        e.target.style.transform = 'scale(1)';
                    }}
                >
                    ✕
                </button>
            </div>
        </>
    );
};

export default Notificacion;

// =============================================================================
// CONTENEDOR DE NOTIFICACIONES (PARA MANEJAR MÚLTIPLES NOTIFICACIONES)
// =============================================================================
/**
 * COMPONENTE: NotificacionContainer
 * 
 * Este componente maneja múltiples notificaciones apiladas.
 * Cada notificación tiene su propio ID y puede cerrarse independientemente.
 * 
 * USO:
 * ```jsx
 * const { agregarNotificacion } = useNotificaciones();
 * agregarNotificacion('Producto agregado', 'exito');
 * ```
 */
export const NotificacionContainer = ({ notificaciones, onRemove }) => {
    return (
        <div style={{
            position: 'fixed',
            bottom: '20px',
            right: '20px',
            display: 'flex',
            flexDirection: 'column-reverse',  // Las nuevas aparecen abajo
            gap: '10px',
            zIndex: 10000
        }}>
            {notificaciones.map((notif) => (
                <Notificacion
                    key={notif.id}
                    mensaje={notif.mensaje}
                    tipo={notif.tipo}
                    duracion={notif.duracion}
                    onClose={() => onRemove(notif.id)}
                />
            ))}
        </div>
    );
};

// =============================================================================
// HOOK PERSONALIZADO: useNotificaciones
// =============================================================================
/**
 * Hook para manejar el estado de las notificaciones
 * Simplifica el uso del sistema de notificaciones en otros componentes
 * 
 * USO:
 * ```jsx
 * const { notificaciones, agregarNotificacion, removerNotificacion } = useNotificaciones();
 * 
 * agregarNotificacion('¡Éxito!', 'exito');
 * agregarNotificacion('Error', 'error');
 * ```
 */
export const useNotificaciones = () => {
    const [notificaciones, setNotificaciones] = React.useState([]);

    /**
     * Agrega una nueva notificación
     * 
     * @param {string} mensaje - El mensaje a mostrar
     * @param {string} tipo - Tipo de notificación ('exito', 'error', etc.)
     * @param {number} duracion - Duración en ms
     */
    const agregarNotificacion = (mensaje, tipo = 'exito', duracion = 3000) => {
        const id = Date.now();  // ID único basado en timestamp

        const nuevaNotificacion = {
            id,
            mensaje,
            tipo,
            duracion
        };

        setNotificaciones(prev => [...prev, nuevaNotificacion]);
    };

    /**
     * Remueve una notificación por ID
     * 
     * @param {number} id - ID de la notificación a remover
     */
    const removerNotificacion = (id) => {
        setNotificaciones(prev => prev.filter(n => n.id !== id));
    };

    return {
        notificaciones,
        agregarNotificacion,
        removerNotificacion
    };
};

